const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let catalog=[],entry=null,currentId='',misses=[],sequence=0;
async function api(path,body){const r=await fetch('/v0/'+path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});return {ok:r.ok,status:r.status,data:await r.json()};}
function output(verdict,reason,metrics=''){ $('#verdict').textContent=verdict;$('#reason').textContent=reason;$('#metrics').textContent=metrics;}
function wire(){const box=$('#circuit').getBoundingClientRect(),svg=$('.wiring');svg.setAttribute('viewBox',`0 0 ${box.width} ${box.height}`);const rect=s=>{const r=$(s).getBoundingClientRect();return {x:r.x-box.x,y:r.y-box.y,w:r.width,h:r.height};},a=rect('.tray'),b=rect('.claim-node'),c=rect('.closure-node'),d=rect('.runtime-node'),e=rect('.terminal');const paths=svg.querySelectorAll('path');paths[0].setAttribute('d',`M${a.x+a.w} ${b.y+b.h/2} H${b.x} M${b.x+b.w} ${b.y+b.h/2} H${c.x} M${c.x+c.w/2} ${c.y+c.h} V${c.y+c.h+17} H${d.x+d.w/2} V${d.y}`);paths[1].setAttribute('d',`M${a.x+a.w/2} ${a.y+a.h} V${box.height-15} H${e.x+e.w/2} V${e.y+e.h}`);paths[2].setAttribute('d',`M${d.x+d.w} ${d.y+d.h/2} H${e.x}`);svg.querySelectorAll('circle').forEach(n=>n.setAttribute('r','0'));}
window.addEventListener('resize',wire);
function groupFiles(files){const groups={};for(const file of files){const dir=file.path.includes('/')?file.path.slice(0,file.path.lastIndexOf('/')):'Package root';(groups[dir]??=[]).push(file);}return Object.entries(groups);}
function graph(e){const full=!!e.replay,recorded=(e.replay?.status||e.replay_status)==='recorded';$('#circuit').className='circuit'+(recorded?' recorded':'');$('#claim-node').innerHTML=`<span class="tag">Entry / subject</span><h3>${esc(e.id)}</h3><b>${esc(e.subject?.name||e.title)}</b><p>${esc(e.claim)}</p><small>${esc(e.subject?.version||'')}</small>`;$('#closure-node').innerHTML=`<span class="tag">Delivered closure</span><h3>${full?e.closure.length+' files':'Manifest unavailable'}</h3>${full?groupFiles(e.closure).map(([dir,files])=>`<details><summary>${esc(dir)} (${files.length})</summary>${files.map(f=>`<p>${esc(f.path)}<code>SHA-256 ${esc(f.sha256)}</code><small>${f.bytes} bytes</small></p>`).join('')}</details>`).join(''):'<p>The mock has only this catalog summary. Inspect the full package on vflab.</p>'}`;$('#runtime-node').innerHTML=`<span class="tag">Replay / requirements</span><h3 class="${recorded?'notice':''}">${recorded?'╱ Open circuit':'● Real replay'}</h3><p>${recorded?'Recorded. Not re-run by fvapi.':'Download the proof and re-check it.'}</p><small>${esc(e.toolchain)}${full?'<br>'+e.requires.map(esc).join(', '):''}</small>`;$('#input-note').textContent=e.check?'Edit the JSON, then run the checker.':'No checker. Select another entry to check input.';$('#input').value=e.check?JSON.stringify(e.check.example_input,null,2):'{}';$('#mode').textContent=recorded?'Replay circuit open':'Circuit ready';wire();}
function dossier(e){const recorded=e.replay.status==='recorded';$('#bundle').hidden=false;$('#bundle').href='/v0/bundles/'+encodeURIComponent(e.id)+'.tar.gz';$('#entry').innerHTML=`<h3>${esc(e.title)}</h3><p class="claim">${esc(e.claim)}</p>${recorded?'<p class="notice">Recorded replay. This proof was not re-run by fvapi.</p>':''}<div class="evidence-grid"><div><h3>Statements to match</h3>${e.statements.map(s=>`<p>${esc(s.name)}<br><small>${esc(s.file)}:${s.line}</small></p><pre>${esc(s.text)}</pre>`).join('')}<h3>Closure files and SHA-256</h3>${groupFiles(e.closure).map(([dir,files])=>`<details ${e.closure.length<8?'open':''}><summary>${esc(dir)} / ${files.length} files</summary><table><thead><tr><th>File</th><th>SHA-256 / size</th></tr></thead><tbody>${files.map(f=>`<tr><td>${esc(f.path)}</td><td><code>${esc(f.sha256)}</code><br>${f.bytes} bytes</td></tr>`).join('')}</tbody></table></details>`).join('')}</div><div><h3>Replay on your machine</h3><pre>${esc(e.replay.command)}</pre><button id="copy">Copy replay command</button><p>${esc(e.replay.note)}</p><dl><dt>Expected axioms</dt><dd>${e.replay.expect_axioms.map(esc).join('<br>')||'None'}</dd><dt>Toolchain and requirements</dt><dd>${esc(e.toolchain)}<br>${e.requires.map(esc).join('<br>')}</dd><dt>Licence</dt><dd>${esc(e.licence.spdx)}</dd><dt>Third-party notices</dt><dd>${e.licence.third_party.map(t=>`${esc(t.name)} / ${esc(t.spdx)}<br>${esc(t.source)}`).join('<br>')||'No third-party notices in this manifest.'}</dd><dt>Subject artifact</dt><dd>${e.subject?.artifact?`${esc(e.subject.artifact.name)}<br>SHA-256 <code>${esc(e.subject.artifact.sha256)}</code><br>${e.subject.artifact.bytes} bytes`:'No separate binary artifact.'}</dd><dt>Source repository</dt><dd>${esc(e.source.repo)}</dd><dt>Source commit</dt><dd><code>${esc(e.source.commit)}</code></dd><dt>Source paths</dt><dd>${e.source.paths.map(esc).join('<br>')}</dd></dl>${recorded?`<h3>Recorded transcript</h3><pre>${esc(e.replay.transcript||'No transcript supplied.')}</pre>`:''}<div id="recheck"></div></div></div>`;$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(e.replay.command);$('#copy').textContent='Command copied';}catch{$('#copy').textContent='Select and copy the command above';}};}
async function select(id){const ticket=++sequence;currentId=id;document.querySelectorAll('[data-entry]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.entry===id)));output('READY','Run a lookup or check.','No check submitted for this entry.');const r=await api('catalog/'+encodeURIComponent(id));if(ticket!==sequence)return;if(r.ok){entry=r.data;graph(entry);dossier(entry);}else{entry=null;const summary=catalog.find(e=>e.id===id);if(!summary)throw Error(r.data.detail);graph(summary);$('#bundle').hidden=true;$('#entry').innerHTML=`<h3>${esc(summary.title)}</h3><p>${esc(summary.claim)}</p><p class="notice">Recorded. Not re-run by fvapi. The full manifest is unavailable in this mock.</p>`;}}
function pins(){ $('#pins').innerHTML='<span>○ Unconnected input pins</span>'+(misses.length?misses.map(m=>`<span class="pin">${esc(m)}</span>`).join(''):'<span>No unmatched request in this session.</span>');}
async function logs(mode='answers'){const r=await api(mode);if(!r.ok)throw Error(r.data.detail);$('#answers').setAttribute('aria-pressed',String(mode==='answers'));$('#demand').setAttribute('aria-pressed',String(mode==='demand'));$('#log-title').textContent=mode==='answers'?'Answers / each lookup and check':'Demand / unmatched requests';const records=mode==='answers'?r.data.answers:r.data.misses;$('#log').innerHTML=records?.length?records.map(x=>`<div class="record"><span>${esc(x.at||x.answer_id||x.demand_id||'Recorded')}</span><span>${esc(x.kind||'Miss')}</span><span>${esc(x.entry_id||JSON.stringify(x.query||x.key||x))}</span><b class="${esc(x.verdict)}">${esc(x.verdict||'Logged')}</b></div>`).join(''):'<p>No records yet. Run a lookup or a check.</p>';if(mode==='demand'){for(const m of (r.data.misses||[])){const key=JSON.stringify(m.query||m.key||m);if(!misses.includes(key))misses.push(key);}pins();$('#log').innerHTML+=`<h3>Counts by key</h3>${(r.data.by_key||[]).map(x=>`<div class="record count-row"><span>${esc(x.key)}</span><span>${x.count} requests</span></div>`).join('')||'<p>No counted demand yet.</p>'}`;}}
async function lookup(){const value=$('#query').value.trim();const r=await api('lookup',{spec_id:value});if(r.ok){await select(r.data.entry?.id||r.data.entry_id||value);$('#circuit').classList.add('lit-evidence');output('FOUND','Matched package. Inspect the statement and replay.','Lookup / HTTP '+r.status);$('#mode').textContent='Matched evidence path';$('#lookup-status').textContent='Match found. Evidence path lit.';}else if(r.status===404){misses.push(value);pins();output('NO MATCH','Logged as demand. Try another specification.','Lookup / HTTP 404');$('#lookup-status').textContent='No match. Logged as demand.';$('#mode').textContent='Unconnected input';}else{output('ERROR',r.data.detail,'Lookup / HTTP '+r.status);}await logs();}
async function check(){let input;try{input=JSON.parse($('#input').value);}catch{output('INPUT ERROR','Invalid JSON. Correct it and run the check again.');return;}const r=await api('checks/'+encodeURIComponent(currentId),input);$('#circuit').classList.remove('lit-evidence','lit-check','rejected');if(r.ok){$('#circuit').classList.add('lit-check');if(r.data.verdict==='reject')$('#circuit').classList.add('rejected');output(r.data.verdict.toUpperCase(),r.data.output?.reason||JSON.stringify(r.data.output),`${r.data.elapsed_ms} ms / ${r.data.ran_on} / exit ${r.data.exit_code}`);$('#mode').textContent='Checker circuit / '+r.data.verdict;if($('#recheck'))$('#recheck').innerHTML='<h3>Re-check this input locally</h3><pre>'+esc(JSON.stringify(r.data.recheck,null,2))+'</pre>';}else{output(r.status===409?'NO CHECKER':'ERROR',r.data.detail+'. Select a checker to run input.','HTTP '+r.status);$('#mode').textContent='Checker circuit unavailable';}await logs();}
function failure(e){output('OFFLINE','The request failed. Reload to try again.',e.message);document.body.dataset.ready='error';}
$('#lookup-form').onsubmit=e=>{e.preventDefault();lookup().catch(failure);};$('#run').onclick=()=>check().catch(failure);$('#example').onclick=()=>{if(entry?.check)$('#input').value=JSON.stringify(entry.check.example_input,null,2);else output('NO CHECKER','Select an entry with a checker to load an example.');};$('#answers').onclick=()=>logs().catch(failure);$('#demand').onclick=()=>logs('demand').catch(failure);
async function init(){const r=await api('catalog');if(!r.ok)throw Error(r.data.detail);catalog=r.data.entries;$('#entry-count').textContent=catalog.length+' entries';$('#catalog').innerHTML=catalog.map(e=>`<button data-entry="${esc(e.id)}" aria-pressed="false"><b>${esc(e.subject?.name||e.title)}</b><span>${esc(e.id)}</span><small>${esc(e.kind)} / ${e.replay_status==='recorded'?'recorded, not re-run':'real replay'}</small></button>`).join('');document.querySelectorAll('[data-entry]').forEach(b=>b.onclick=()=>select(b.dataset.entry).catch(failure));const manifests=await Promise.all(catalog.map(async e=>(await api('catalog/'+encodeURIComponent(e.id))).data));const checker=manifests.find(e=>e.check!=null);const state=new URLSearchParams(location.search).get('state')||'catalog';const recorded=catalog.find(e=>e.replay_status==='recorded');await select(['recorded','check-409'].includes(state)?recorded.id:(checker?.id||catalog[0].id));await logs();if(state==='lookup-hit'||state==='lookup-miss'){$('#query').value=state==='lookup-hit'?checker.id:'unmatched.example';await lookup();}if(['check-accept','check-reject','check-409'].includes(state)){if(state==='check-reject'){const input=JSON.parse($('#input').value);input.rows[1].weights[0]+=1;$('#input').value=JSON.stringify(input,null,2);}await check();}if(state==='demand')await logs('demand');if(state==='entry')$('.dossier').scrollIntoView();if(['demand','answers'].includes(state))$('.recorder').scrollIntoView();wire();document.body.dataset.ready='true';}init().catch(failure);
